  function nearestFree(i,j){ if(!blk[j*gw+i]) return [i,j]; for(let r=1;r<8;r++) for(let dj=-r;dj<=r;dj++) for(let di=-r;di<=r;di++){ const a=i+di,b=j+dj; if(a>=0&&b>=0&&a<gw&&b<gh&&!blk[b*gw+a]) return [a,b]; } return [i,j]; }
