  function crewStep(c,tx,ty,dt){ if(!c.path||T-(c.pT||-9)>1.0){ c.pT=T; c.path=Math.hypot(tx-c.x,ty-c.y)>1.2?astar(c.x,c.y,tx,ty):null; c.pi=0; } if(!c.path) { c.moving=false; return; } let rem=2.3*dt; c.moving=true; while(rem>0&&c.pi<c.path.length){ const [px,py]=c.path[c.pi]; const d=Math.hypot(px-c.x,py-c.y); if(d<=rem){ c.x=px; c.y=py; rem-=d; c.pi++; } else { c.x+=(px-c.x)/d*rem; c.y+=(py-c.y)/d*rem; c.dir=Math.atan2(py-c.y,px-c.x); rem=0; } } }
