    const dur=Math.max(0.3,d/45); sim.fx.push({t:'rkt',x0:a.x+Math.cos(a.dir)*0.6,y0:a.y+Math.sin(a.dir)*0.6,x1:ex,y1:ey,t0:T,dur,hit,face,done:false,by:a.id}); sim.fx.push({t:'bb',x:a.x,y:a.y,dir:a.dir+Math.PI,t0:T});
